/* Minimal HTMX-compatible library for RAG-Bachelor.
 * Implements: hx-get, hx-post, hx-target, hx-swap (innerHTML/outerHTML),
 *             hx-vals, hx-indicator, hx-encoding, hx-trigger, hx-include.
 * GET requests are serialized into the query string from the triggering
 * element (a <form>'s FormData, or a single named input/select) plus
 * hx-vals and hx-include. hx-include takes a CSS selector; each matched
 * element contributes its FormData (if a <form>) or its own name/value.
 */
(function () {
  "use strict";

  var IND_CLASS = "htmx-request";

  function showInd(sel) {
    if (!sel) return null;
    var el = document.querySelector(sel);
    if (el) el.classList.add(IND_CLASS);
    return el;
  }

  function hideInd(el) {
    if (el) el.classList.remove(IND_CLASS);
  }

  function resolveTarget(el, sel) {
    if (!sel || sel === "this") return el;
    return document.querySelector(sel);
  }

  // Collect request params from *el* (a <form>'s fields, or a single named
  // input/select/checkbox/radio) plus an *extra* plain object (from hx-vals).
  // Shared by GET query-string building and non-multipart POST bodies.
  function appendField(p, node) {
    if (node.tagName === "FORM") {
      new FormData(node).forEach(function (v, k) { p.append(k, v); });
    } else if (node.name) {
      if (node.type === "checkbox" || node.type === "radio") {
        if (node.checked) p.append(node.name, node.value);
      } else {
        p.append(node.name, node.value);
      }
    }
  }

  function buildParams(el, extra, includeSel) {
    var p = new URLSearchParams();
    appendField(p, el);
    if (includeSel) {
      document.querySelectorAll(includeSel).forEach(function (node) { appendField(p, node); });
    }
    Object.keys(extra).forEach(function (k) { p.append(k, extra[k]); });
    return p;
  }

  function doSwap(target, html, swap) {
    if (!target) return;
    if ((swap || "innerHTML") === "outerHTML") {
      var tmp = document.createElement("div");
      tmp.innerHTML = html;
      var nodes = Array.from(tmp.childNodes);
      target.replaceWith.apply(target, nodes);
      nodes.forEach(function (n) { if (n.querySelectorAll) processAll(n); });
    } else {
      target.innerHTML = html;
      processAll(target);
    }
  }

  // Security: innerHTML is used to swap server-supplied HTML fragments.
  // We only accept same-origin responses (enforced below) and Jinja2
  // auto-escaping ensures all user-supplied values in templates are escaped.
  // This app runs on localhost only; never expose it to an untrusted network.
  function fire(method, url, body, encoding, target, swap, indSel) {
    var ind = showInd(indSel);

    // XHR for multipart — fetch + FormData is unreliable for file uploads in Firefox.
    if (encoding === "multipart/form-data") {
      var xhr = new XMLHttpRequest();
      xhr.open(method, url);
      xhr.onload = function () {
        hideInd(ind);
        if (xhr.status >= 200 && xhr.status < 300) {
          doSwap(target, xhr.responseText, swap);
        } else {
          console.error("[htmx] HTTP " + xhr.status, xhr.responseText);
        }
      };
      xhr.onerror = function () { hideInd(ind); console.error("[htmx] XHR network error"); };
      xhr.send(body);
      return;
    }

    var opts = { method: method };
    if (body !== null) {
      opts.headers = { "Content-Type": "application/x-www-form-urlencoded" };
      opts.body = body;
    }
    fetch(url, opts)
      .then(function (r) {
        // Reject cross-origin responses — all our endpoints are same-origin.
        var origin = window.location.origin;
        if (r.url && !r.url.startsWith(origin)) {
          console.error("[htmx] Rejected cross-origin response:", r.url);
          hideInd(ind);
          return "";
        }
        return r.text();
      })
      .then(function (html) { if (html !== "") { hideInd(ind); doSwap(target, html, swap); } })
      .catch(function (e) { hideInd(ind); console.error("[htmx]", e); });
  }

  function parseDelay(s) {
    var m = /^(\d+(?:\.\d+)?)(ms|s)?$/.exec(s);
    if (!m) return 0;
    var n = parseFloat(m[1]);
    return m[2] === "s" ? n * 1000 : n;
  }

  // Parses the subset of htmx's hx-trigger mini-language this app relies on:
  // comma-separated "event [changed] [delay:Xms|Xs] [from:<selector>]" specs.
  function parseTriggers(str) {
    return str.split(",").map(function (part) {
      var tokens = part.trim().split(/\s+/);
      var spec = { event: tokens[0], changed: false, delay: 0, from: null };
      for (var i = 1; i < tokens.length; i++) {
        var t = tokens[i];
        if (t === "changed") spec.changed = true;
        else if (t.indexOf("delay:") === 0) spec.delay = parseDelay(t.slice(6));
        else if (t.indexOf("from:") === 0) spec.from = t.slice(5);
      }
      return spec;
    });
  }

  function bindElement(el) {
    if (el._hx) return;
    var hxPost = el.getAttribute("hx-post");
    var hxGet  = el.getAttribute("hx-get");
    var method = hxPost ? "POST" : hxGet ? "GET" : null;
    if (!method) return;
    el._hx = true;

    var url       = hxPost || hxGet || "";
    var targetSel = el.getAttribute("hx-target");
    var swap      = el.getAttribute("hx-swap")      || "innerHTML";
    var valsRaw   = el.getAttribute("hx-vals")      || null;
    var indSel    = el.getAttribute("hx-indicator") || null;
    var encoding  = el.getAttribute("hx-encoding")  || null;
    var includeSel = el.getAttribute("hx-include")  || null;
    var defTrig   = el.tagName === "FORM" ? "submit" : "click";
    var triggers  = parseTriggers(el.getAttribute("hx-trigger") || defTrig);

    function doFire(e) {
      if (e) e.preventDefault();
      // hx-confirm: value is a plain text attribute — never injected into JS
      var confirmMsg = el.getAttribute("hx-confirm");
      if (confirmMsg && !window.confirm(confirmMsg)) return;
      var target = resolveTarget(el, targetSel);
      var body      = null;
      var requestUrl = url;

      var extra = {};
      if (valsRaw) {
        try { extra = JSON.parse(valsRaw); } catch (_) {}
      }

      if (method === "GET") {
        var qs = buildParams(el, extra, includeSel).toString();
        if (qs) requestUrl = url + (url.indexOf("?") === -1 ? "?" : "&") + qs;
      } else {
        var isMulti = encoding === "multipart/form-data" ||
                      (el.tagName === "FORM" && el.enctype === "multipart/form-data");
        if (isMulti && el.tagName === "FORM") {
          var fd = new FormData(el);
          Object.keys(extra).forEach(function (k) { fd.append(k, extra[k]); });
          body = fd;
          encoding = "multipart/form-data";
        } else {
          body = buildParams(el, extra, includeSel).toString();
        }
      }

      fire(method, requestUrl, body, encoding, target, swap, indSel);
    }

    var delayTimer = null;
    triggers.forEach(function (spec) {
      // "load" isn't a real event on arbitrary elements — htmx fires it once,
      // right when the element is processed (matches index_progress.html's poll).
      if (spec.event === "load") {
        if (spec.delay) setTimeout(function () { doFire(null); }, spec.delay);
        else doFire(null);
        return;
      }
      var source = spec.from ? document.querySelector(spec.from) : el;
      if (!source) return;
      source.addEventListener(spec.event, function (e) {
        if (spec.changed) {
          var val = source.value;
          if (source._hxLastVal === val) return;
          source._hxLastVal = val;
        }
        if (spec.delay) {
          clearTimeout(delayTimer);
          delayTimer = setTimeout(function () { doFire(e); }, spec.delay);
        } else {
          doFire(e);
        }
      });
    });
  }

  function processAll(root) {
    root = root || document;
    // querySelectorAll only finds descendants — an outerHTML swap replaces a
    // node with a fresh one that carries its own hx-get/hx-post, so the root
    // itself must be checked too or it never gets rebound (e.g. the status
    // poller in index_progress.html, which re-swaps itself every tick).
    if (root.nodeType === 1 && (root.hasAttribute("hx-post") || root.hasAttribute("hx-get"))) {
      bindElement(root);
    }
    if (root.querySelectorAll) root.querySelectorAll("[hx-post],[hx-get]").forEach(bindElement);
  }

  document.addEventListener("DOMContentLoaded", function () { processAll(document); });
  window.htmx = { processAll: processAll };
})();
